__NUXT_JSONP__("/tw/school-calendar", {data:[{details:{slug:"tw",pageTitle:"校歷 | Mentor Language Institute",pageDescription:"課程開始日期根據F1或非F1學生而有所不同。",title:"校歷",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003E黃色\u003C\u002Ffont\u003E: 課程開始日（學期）\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003E綠色\u003C\u002Ffont\u003E： 放假（假期）"],schoolCalendar:{title:"校歷（課程開始日）",description:["\u003Cspan class=\"ymarker\"\u003E課程開始日期根據F1或非F1學生而有所不同。\u003C\u002Fspan\u003E"],lists:[{key:"非F1學生指學生沒有學生簽證。",value:["可以在任何一個週一開始上課。\u003Cbr\u003E 如果星期一是節假日，那麼該週的課程開始日期將是星期二。"]},{key:"F1學生簽證是指擁有學生簽證的學生。",value:["開學日請參照校歷中黃色的日期。 ","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"關於到達美國日期的常見問題",lists:[{key:"\u003Cb\u003E問：距離開學多久我可以抵達美國？ \u003C\u002Fb\u003E",value:["答：MLI沒有要求學生必須在什麼時間抵達美國。不過我們學校大部分學生會距開學日提前1到2天到達美國。 "],note:"注：國際學生可在開學日前30天入境美國。"},{key:"\u003Cb\u003E問：是否可以在開學前入住學生宿舍？\u003C\u002Fb\u003E",value:["答：可以。您可以在您需要的時間入住。 \u003Cbr \u002F\u003E如果您有任何的問題，請隨時和我們聯繫。"]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:30.896Z",updatedAt:"2026-04-24T11:47:24.381Z"}}],fetch:{},mutations:void 0});